import time
from datetime import datetime

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    try:
        while True:
            for conn in psutil.net_connections(kind='inet'):
                if conn.status == 'ESTABLISHED' and conn.laddr.ip == host:
                    logs.append({
                        "timestamp": datetime.now().isoformat(),
                        "source": conn.raddr.ip if conn.raddr else "Unknown"
                    })
            time.sleep(interval_s)
    except KeyboardInterrupt:
        return logs
