import os

def find_writable_files(directory: str) -> list[str]:
    writable = []
    for root, _, files in os.walk(directory):
        for file in files:
            path = os.path.join(root, file)
            try:
                if os.access(path, os.W_OK):
                    writable.append(path)
            except (PermissionError, OSError):
                continue
    return writable
