from scapy.all import rdpcap, DNS, DNSQR
import collections

def analyze_dns_traffic(pcap_file: str) -> dict:
    packets = rdpcap(pcap_file)
    queries = [pkt[DNSQR].qname.decode() for pkt in packets if DNS in pkt and pkt[DNS].qr == 0]

    results = {
        "suspicious_domains": [],
        "high_volume_domains": []
    }

    counts = collections.Counter(queries)
    for domain, count in counts.items():
        name = domain.split('.')[0]
        # Simple DGA/Tunneling heuristics: length > 20 or high entropy/volume
        if len(name) > 20 or count > 100:
            results["suspicious_domains"].append(domain)
        if count > 500:
            results["high_volume_domains"].append(domain)

    return results
```

